// 1. Получаем данные из предыдущих нод
// Замените 'Calculate Statistics' на имя вашей ноды со статистикой
const statsNode = $('Calculate Statistics').first().json; 
const summary = statsNode.summary;
const delta = statsNode.delta;
const groupedData = statsNode.groupedData;

// Замените 'OpenAI' на имя вашей ноды с нейросетью
let aiComment = "Комментарий от AI временно недоступен.";
try {
  aiComment = $input.first().json.text;
} catch (e) {
  // Если нода OpenAI упала, письмо все равно отправится
  console.log("Ошибка получения данных от Ai");
}

// 2. Вспомогательная функция для красивого отображения дельты
function formatDelta(val, inverse = false) {
  if (val === 0) return `<span style="color: #666;">0</span>`;
  const isPositive = val > 0;
  // Если inverse = true (например, для багов), то рост — это плохо (красный)
  const color = (isPositive !== inverse) ? '#28a745' : '#d73a49'; 
  const sign = isPositive ? '+' : '';
  return `<span style="color: ${color}; font-weight: bold;">${sign}${val}</span>`;
}

// 3. Формируем блок со статистикой
let summaryHtml = `
  <div style="margin-bottom: 20px; padding: 15px; background-color: #f6f8fa; border-radius: 6px; border: 1px solid #e1e4e8;">
    <h3 style="margin-top: 0; color: #24292e;">📈 Краткие итоги</h3>
    <table style="width: 100%; text-align: left; font-size: 14px;">
      <tr>
        <td style="padding: 4px 0;"><b>Всего задач:</b> ${summary.total} (${formatDelta(delta.total)})</td>
        <td style="padding: 4px 0;"><b>Открыто:</b> ${summary.open} (${formatDelta(delta.open)})</td>
      </tr>
      <tr>
        <td style="padding: 4px 0;"><b>Закрыто:</b> ${summary.closed} (${formatDelta(delta.closed)})</td>
        <td style="padding: 4px 0;"><b>Баги:</b> ${summary.bugs} (${formatDelta(delta.bugs, true)})</td>
      </tr>
    </table>
    <p style="margin-bottom: 0; font-size: 14px; margin-top: 10px;">
      🏆 <b>Самый активный автор:</b> @${summary.top_author}
    </p>
  </div>
`;

// 4. Формируем блок для AI-комментария
let aiHtml = `
  <div style="margin-bottom: 25px; padding: 15px; background-color: #f1f8ff; border-left: 4px solid #0366d6; border-radius: 4px;">
    <h3 style="margin-top: 0; color: #0366d6; font-size: 16px;">🤖 AI-комментарий недели</h3>
    <p style="margin-bottom: 0; font-size: 14px; line-height: 1.5; color: #24292e; font-style: italic;">
      "${aiComment}"
    </p>
  </div>
`;

// 5. Формируем HTML-таблицу
let tableHtml = `
  <h3 style="color: #24292e;">📋 Детализация по задачам</h3>
  <table style="width: 100%; border-collapse: collapse; font-size: 13px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif;">
    <thead>
      <tr style="background-color: #f6f8fa; border-bottom: 2px solid #e1e4e8; text-align: left;">
        <th style="padding: 10px; border: 1px solid #dfe2e5;">Тип</th>
        <th style="padding: 10px; border: 1px solid #dfe2e5;">Автор</th>
        <th style="padding: 10px; border: 1px solid #dfe2e5;">Задача</th>
        <th style="padding: 10px; border: 1px solid #dfe2e5;">Статус</th>
      </tr>
    </thead>
    <tbody>
`;

let rowCount = 0;
// Проходимся по сгруппированным данным
for (const type in groupedData) {
  for (const author in groupedData[type]) {
    const issues = groupedData[type][author];

    issues.forEach((issue, index) => {
      // Чередование цветов строк (зебра)
      const bgColor = rowCount % 2 === 0 ? '#ffffff' : '#f9f9f9';

      // Чтобы не дублировать Тип и Автора в каждой строке (визуальная группировка)
      const typeCell = index === 0 
        ? `<td style="padding: 10px; border: 1px solid #dfe2e5; background-color: ${bgColor};"><b>${type}</b></td>` 
        : `<td style="padding: 10px; border: 1px solid #dfe2e5; background-color: ${bgColor};"></td>`;

      const authorCell = index === 0 
        ? `<td style="padding: 10px; border: 1px solid #dfe2e5; background-color: ${bgColor};">@${author}</td>` 
        : `<td style="padding: 10px; border: 1px solid #dfe2e5; background-color: ${bgColor};"></td>`;

      // Статус с эмодзи и цветом
      const statusBadge = issue.state === 'open' 
        ? '<span style="color: #d73a49; font-weight: bold;">🔴 Open</span>' 
        : '<span style="color: #28a745; font-weight: bold;">🟢 Closed</span>';

      tableHtml += `
        <tr>
          ${typeCell}
          ${authorCell}
          <td style="padding: 10px; border: 1px solid #dfe2e5; background-color: ${bgColor};">
            <a href="${issue.url}" style="color: #0366d6; text-decoration: none;">#${issue.number} ${issue.title}</a>
          </td>
          <td style="padding: 10px; border: 1px solid #dfe2e5; background-color: ${bgColor};">
            ${statusBadge}
          </td>
        </tr>
      `;
      rowCount++;
    });
  }
}

tableHtml += `
    </tbody>
  </table>
`;

// 6. Собираем все вместе в финальное письмо
const finalHtml = `
  <div style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif; max-width: 800px; margin: 0 auto; color: #24292e;">

    ${summaryHtml}
    ${aiHtml}
    ${tableHtml}

    <p style="font-size: 12px; color: #6a737d; text-align: center; margin-top: 30px;">
      Автоматически сгенерировано в n8n • ${new Date().toLocaleDateString('ru-RU')}
    </p>
  </div>
`;

// Возвращаем результат для отправки
return [{
  json: {
    htmlContent: finalHtml,
    plainTextFallback: "Ваш почтовый клиент не поддерживает HTML. Пожалуйста, используйте современный клиент." // На всякий случай
  }
}];

const allItems = $input.all();
const uniqueIssues = {};

// Безопасно достаем данные за прошлую неделю. 
// Если база пуста (первый запуск), подставится 0
const prevNode = $('Get row(s)').first();
const prevStats = { 
  total: prevNode?.json?.TotalIssues ?? 0, 
  open: prevNode?.json?.OpenedIssues ?? 0, 
  closed: prevNode?.json?.ClosedIssues ?? 0, 
  bugs: prevNode?.json?.Bugs ?? 0 
};

// 1. РАЗДЕЛЯЕМ ДАННЫЕ
for (const item of allItems) {
  const data = item.json;

  // Если это задача из GitHub И ЭТО НЕ PULL REQUEST (!data.pull_request)
  if (data.html_url && !data.pull_request) {
    // Дедупликация с приоритетом статуса "closed"
    if (!uniqueIssues[data.id] || String(data.state).toLowerCase() === 'closed') {
      uniqueIssues[data.id] = data;
    }
  } 
}

// 2. СЧИТАЕМ СТАТИСТИКУ
const groupedData = {};
let currentOpen = 0;
let currentClosed = 0;
let currentBugs = 0;
const authorCounts = {};

for (const id in uniqueIssues) {
  const issue = uniqueIssues[id];

  // Приводим к строке и нижнему регистру
  const state = String(issue.state || '').toLowerCase(); 

  if (state === 'open') currentOpen++;
  if (state === 'closed') currentClosed++;

  let type = 'Other';
  if (issue.labels && issue.labels.length > 0) {
    type = typeof issue.labels[0] === 'string' ? issue.labels[0] : issue.labels[0].name;
    if (type.toLowerCase().includes('bug')) currentBugs++;
  }

  const author = issue.user ? issue.user.login : 'Unknown';
  authorCounts[author] = (authorCounts[author] || 0) + 1;

  if (!groupedData[type]) groupedData[type] = {};
  if (!groupedData[type][author]) groupedData[type][author] = [];

  groupedData[type][author].push({
    number: issue.number,
    title: issue.title,
    url: issue.html_url,
    state: state,
    date: new Date(issue.created_at).toLocaleDateString('ru-RU')
  });
}

const currentTotal = Object.keys(uniqueIssues).length;

// Ищем самого активного автора
let topAuthor = 'None';
let maxIssues = 0;
for (const author in authorCounts) {
  if (authorCounts[author] > maxIssues) {
    maxIssues = authorCounts[author];
    topAuthor = author;
  }
}

// 3. СЧИТАЕМ ДЕЛЬТУ
const delta = {
  total: currentTotal - prevStats.total,
  open: currentOpen - prevStats.open,
  closed: currentClosed - prevStats.closed,
  bugs: currentBugs - prevStats.bugs
};

// 4. ВОЗВРАЩАЕМ ЧИСТЫЙ РЕЗУЛЬТАТ
return [{
  json: {
    summary: {
      total: currentTotal,
      open: currentOpen,
      closed: currentClosed,
      bugs: currentBugs,
      top_author: topAuthor
    },
    delta: delta,
    groupedData: groupedData
  }
}];

